#include "Mapper083.h"
#include "../state_io.h"
#include <algorithm>
#include <cstring>
void Mapper083::reset(){std::memset(regs,0,sizeof(regs));std::memset(exRegs,0,sizeof(exRegs));is2k=isNot2k=irqEnabled=irqActive=false;mode=bank=0;irqCounter=0;update();}
void Mapper083::update(){switch(mode&3u){case 0:mirrorMode=1;break;case 1:mirrorMode=0;break;case 2:mirrorMode=3;break;default:mirrorMode=4;break;}if(is2k&&!isNot2k){const uint8_t r[4]={regs[0],regs[1],regs[6],regs[7]};for(int i=0;i<4;i++){chr1[i*2]=uint16_t(r[i]<<1);chr1[i*2+1]=uint16_t((r[i]<<1)+1);}}else for(int i=0;i<8;i++)chr1[i]=uint16_t(regs[i]|((bank&0x30u)<<4));uint16_t pc=std::max<uint16_t>(1,uint16_t(prgBanks*2u));if(mode&0x40u){uint16_t b=uint16_t((bank&0x3Fu)<<1);prg8[0]=b;prg8[1]=uint16_t(b+1);b=uint16_t(((bank&0x30u)|0x0Fu)<<1);prg8[2]=b;prg8[3]=uint16_t(b+1);}else{prg8[0]=regs[8];prg8[1]=regs[9];prg8[2]=regs[10];prg8[3]=uint16_t(pc-1);}}
bool Mapper083::cpuReadDirect(uint16_t a,uint8_t&d){if(a==0x5000){d=0;return true;}if(a>=0x5100&&a<=0x5103){d=exRegs[a&3];return true;}return false;}
bool Mapper083::cpuWriteDirect(uint16_t a,uint8_t d){if(a>=0x5100&&a<=0x5103){exRegs[a&3]=d;return true;}return false;}
bool Mapper083::cpuMapRead(uint16_t a,uint32_t&m){if(a<0x8000)return false;uint16_t c=std::max<uint16_t>(1,uint16_t(prgBanks*2u));uint8_t s=uint8_t((a-0x8000)>>13);m=uint32_t(prg8[s]%c)*0x2000u+(a&0x1FFFu);return true;}
bool Mapper083::cpuMapWrite(uint16_t a,uint32_t&m,uint8_t d){if(a<0x8000)return false;if(a>=0x8300&&a<=0x8302){mode&=0xBFu;regs[a-0x8300+8]=d;update();}else if(a>=0x8310&&a<=0x8317){regs[a-0x8310]=d;if(a>=0x8312&&a<=0x8315)isNot2k=true;update();}else switch(a){case 0x8000:is2k=true;bank=d;mode|=0x40u;update();break;case 0xB000:case 0xB0FF:case 0xB1FF:bank=d;mode|=0x40u;update();break;case 0x8100:mode=uint8_t(d|(mode&0x40u));update();break;case 0x8200:irqCounter=uint16_t((irqCounter&0xFF00u)|d);irqActive=false;break;case 0x8201:irqEnabled=(mode&0x80u)!=0;irqCounter=uint16_t((irqCounter&0x00FFu)|(uint16_t(d)<<8));break;default:break;}m=0;return true;}
bool Mapper083::ppuMapRead(uint16_t a,uint32_t&m){if(a>0x1FFF)return false;uint16_t c=std::max<uint16_t>(1,uint16_t(chrBanks?chrBanks*8u:8u));uint8_t s=uint8_t(a>>10);m=uint32_t(chr1[s]%c)*0x400u+(a&0x3FFu);return true;}bool Mapper083::ppuMapWrite(uint16_t a,uint32_t&m,uint8_t){return chrBanks==0&&ppuMapRead(a,m);}
void Mapper083::cpuClock(){if(!irqEnabled)return;--irqCounter;if(irqCounter==0){irqEnabled=false;irqCounter=0xFFFFu;irqActive=true;}}
void Mapper083::saveState(std::vector<uint8_t>&o)const{using namespace ciphernes_state;write_bytes(o,regs,sizeof(regs));write_bytes(o,exRegs,sizeof(exRegs));for(uint16_t v:prg8)write_u16(o,v);for(uint16_t v:chr1)write_u16(o,v);write_bool(o,is2k);write_bool(o,isNot2k);write_bool(o,irqEnabled);write_bool(o,irqActive);write_u8(o,mode);write_u8(o,bank);write_u8(o,mirrorMode);write_u16(o,irqCounter);}bool Mapper083::loadState(const uint8_t*&p,const uint8_t*e){using namespace ciphernes_state;if(!read_bytes(p,e,regs,sizeof(regs))||!read_bytes(p,e,exRegs,sizeof(exRegs)))return false;for(uint16_t&v:prg8)if(!read_u16(p,e,v))return false;for(uint16_t&v:chr1)if(!read_u16(p,e,v))return false;return read_bool(p,e,is2k)&&read_bool(p,e,isNot2k)&&read_bool(p,e,irqEnabled)&&read_bool(p,e,irqActive)&&read_u8(p,e,mode)&&read_u8(p,e,bank)&&read_u8(p,e,mirrorMode)&&read_u16(p,e,irqCounter);}
